SELECT sal AS s
FROM (SELECT 300 sal FROM DUAL UNION ALL SELECT 100 sal FROM DUAL)
ORDER BY s;

SELECT ename, sal
FROM (SELECT 'B' ename, 200 sal FROM DUAL UNION ALL SELECT 'A' ename, 300 sal FROM DUAL)
ORDER BY 2 DESC;

SELECT v
FROM (SELECT 10 v FROM DUAL UNION ALL SELECT NULL v FROM DUAL UNION ALL SELECT 20 v FROM DUAL)
ORDER BY v ASC;
